:root {
  --dark-color: oklch(0.176746 0.011438 260.635176);
  --dark: oklch(0.176746 0.011438 260.635176);
  --gray-color: oklch(0.973048 0.006996 268.548104);
  --gray: oklch(0.973048 0.006996 268.548104);
  --accent-color: oklch(0.713740 0.143381 254.624021);
  --accent: oklch(0.713740 0.143381 254.624021);
  --danger-color: oklch(0.538572 0.193727 26.724902);
  --danger: oklch(0.538572 0.193727 26.724902);
  --heading-color: oklch(0.12 0.02 200);
  --primary-color: oklch(0.488198 0.217165 264.376304);
  --primary: oklch(0.488198 0.217165 264.376304);
  --success-color: oklch(0.527299 0.137103 150.069279);
  --success: oklch(0.527299 0.137103 150.069279);
  --warning-color: oklch(0.768590 0.164659 70.080390);
  --warning: oklch(0.768590 0.164659 70.080390);
  --background-color: oklch(1 0 0);
  --background: oklch(1 0 0);
  --foreground-color: oklch(0.176746 0.011438 260.635176);
  --foreground: oklch(0.176746 0.011438 260.635176);
  --primary-foreground: white;
  --gray-foreground: oklch(0.176746 0.011438 260.635176);
  --font-body: "Montserrat", system-ui, sans-serif;
  --font-heading: "Montserrat Alternates", system-ui, sans-serif;
  --radius: 0.625rem;
  --card-border-width: 1px;
  --card-border-color: oklch(0.95 0 0);
  --heading-weight: 700;
}

.font-heading { font-family: var(--font-heading); }
.font-body { font-family: var(--font-body); }

/* Override heading weight */
h1, h2, h3, h4, h5, h6 { font-weight: var(--heading-weight) !important; }
